const body = $input.first().json.body || $input.first().json;

if (!body || typeof body.message !== 'string' || body.message.trim() === '') {
  return {
    json: {
      success: false,
      status: 'INVALID_REQUEST',
      error: 'message is required and cannot be empty'
    }
  };
}

const message = body.message.trim();
const conversationId = body.conversationId || `conv-${Date.now()}`;
const agentId = body.agentId || 'agent-v1';
const agentVersion = body.agentVersion || 'v1.0.0';

const systemPrompt = `You are a helpful AI assistant. Answer the user's exact question accurately, clearly, and directly. Never answer a different topic from the user's question.`;

return {
  json: {
    success: true,
    message,
    conversationId,
    agentId,
    agentVersion,
    systemPrompt,
    timestamp: new Date().toISOString()
  }
};

const input = $('Validate & Sanitize Input').first().json;
const agent = $input.first().json;

const agentAnswer = agent.output || agent.text || agent.response || '';

if (!agentAnswer || agentAnswer.trim() === '') {
  return {
    json: {
      ...input,
      success: false,
      status: 'AI_GENERATION_FAILED',
      answer: null,
      evaluationUserPrompt: null,
      evaluatorSystemPrompt: null
    }
  };
}

const evaluatorSystemPrompt = `You are an expert AI Response Quality Evaluator.

Evaluate the AI response against the original user question.

First determine whether the response answers the actual topic requested.

If the response is completely off-topic, this is a critical failure.

Score these five criteria from 0 to 10:
1. correctness
2. relevance
3. completeness
4. clarity
5. instruction_following

Calculate:
overall_score = (correctness + relevance + completeness + clarity + instruction_following) / 5

Verdict:
8.0-10.0 = PASS
6.0-7.9 = NEEDS_IMPROVEMENT
0.0-5.9 = FAIL

Return ONLY valid JSON. No markdown and no code fences.

Required schema:
{
  "correctness": 0,
  "relevance": 0,
  "completeness": 0,
  "clarity": 0,
  "instruction_following": 0,
  "overall_score": 0,
  "verdict": "FAIL",
  "strengths": [],
  "weaknesses": [],
  "improvement_suggestions": []
}`;

const evaluationUserPrompt = `[ORIGINAL USER QUESTION]\n${input.message}\n\n[AI AGENT RESPONSE]\n${agentAnswer}`;

return {
  json: {
    ...input,
    agentAnswer,
    evaluatorSystemPrompt,
    evaluationUserPrompt
  }
};

const context = $('Prepare Evaluation Prompt').first().json;
const result = $input.first().json;

if (context.success === false || !context.agentAnswer) {
  return {
    json: {
      success: false,
      status: 'AI_SERVICE_UNAVAILABLE',
      conversationId: context.conversationId,
      agentId: context.agentId,
      agentVersion: context.agentVersion,
      userInput: context.message,
      answer: null,
      evaluation: null,
      error: 'The AI agent could not generate a response.'
    }
  };
}

let text = result.output || result.text || result.response || '';
text = String(text).replace(/^```json\\s*/i, '').replace(/^```\\s*/i, '').replace(/```$/g, '').trim();

let evaluation;

try {
  evaluation = JSON.parse(text);
} catch (error) {
  return {
    json: {
      success: false,
      status: 'EVALUATION_PARSE_ERROR',
      conversationId: context.conversationId,
      agentId: context.agentId,
      agentVersion: context.agentVersion,
      userInput: context.message,
      answer: context.agentAnswer,
      evaluation: null,
      error: 'Evaluator did not return valid JSON.'
    }
  };
}

const scores = [
  Number(evaluation.correctness ?? 0),
  Number(evaluation.relevance ?? 0),
  Number(evaluation.completeness ?? 0),
  Number(evaluation.clarity ?? 0),
  Number(evaluation.instruction_following ?? 0)
];

const overall = Number((scores.reduce((a, b) => a + b, 0) / 5).toFixed(1));

let verdict = 'FAIL';
if (overall >= 8) verdict = 'PASS';
else if (overall >= 6) verdict = 'NEEDS_IMPROVEMENT';

return {
  json: {
    success: true,
    status: 'COMPLETED',
    conversationId: context.conversationId,
    agentId: context.agentId,
    agentVersion: context.agentVersion,
    userInput: context.message,
    answer: context.agentAnswer,
    evaluation: {
      correctness: scores[0],
      relevance: scores[1],
      completeness: scores[2],
      clarity: scores[3],
      instruction_following: scores[4],
      overall_score: overall,
      verdict,
      strengths: Array.isArray(evaluation.strengths) ? evaluation.strengths : [],
      weaknesses: Array.isArray(evaluation.weaknesses) ? evaluation.weaknesses : [],
      improvement_suggestions: Array.isArray(evaluation.improvement_suggestions) ? evaluation.improvement_suggestions : []
    },
    createdAt: new Date().toISOString()
  }
};
